/**
 * Typed callback surface implemented by the platform shell.
 *
 * Implementations must be thread-safe; callbacks fire from dispatcher worker
 * threads, never while the handle holds its state lock, so hosts may call
 * back into the handle (for example `pair_poll`) from any callback.
 */
public protocol CoreCallbacks: AnyObject, Sendable {

    /**
     * Fresh live clip; core has already durably recorded history.
     */
    func onClip(item: FfiClipItem) throws

    /**
     * Mailbox or stale clip; the returned disposition decides whether the
     * history entry is promoted from `RemoteDeferred` to `Remote`.
     */
    func onMailboxClip(item: FfiClipItem) throws  -> MailboxDisposition

    /**
     * Typed lifecycle status transition.
     */
    func onStatus(status: CoreStatus)

}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceCoreCallbacks {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceCoreCallbacks] = [UniffiVTableCallbackInterfaceCoreCallbacks(
        onClip: { (
            uniffiHandle: UInt64,
            item: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceCoreCallbacks.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.onClip(
                     item: try FfiConverterTypeFfiClipItem_lift(item)
                )
            }


            let writeReturn = { () }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeCoreError_lower
            )
