// FfiConverter protocol for callback interfaces
#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterCallbackInterfaceCoreCallbacks {
    fileprivate static let handleMap = UniffiHandleMap<CoreCallbacks>()
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
extension FfiConverterCallbackInterfaceCoreCallbacks : FfiConverter {
    typealias SwiftType = CoreCallbacks
    typealias FfiType = UInt64

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func lift(_ handle: UInt64) throws -> SwiftType {
        try handleMap.get(handle: handle)
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SwiftType {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func lower(_ v: SwiftType) -> UInt64 {
        return handleMap.insert(obj: v)
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func write(_ v: SwiftType, into buf: inout [UInt8]) {
        writeInt(&buf, lower(v))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterCallbackInterfaceCoreCallbacks_lift(_ handle: UInt64) throws -> CoreCallbacks {
    return try FfiConverterCallbackInterfaceCoreCallbacks.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterCallbackInterfaceCoreCallbacks_lower(_ v: CoreCallbacks) -> UInt64 {
    return FfiConverterCallbackInterfaceCoreCallbacks.lower(v)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterSequenceTypeFfiHistoryItem: FfiConverterRustBuffer {
    typealias SwiftType = [FfiHistoryItem]

    public static func write(_ value: [FfiHistoryItem], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeFfiHistoryItem.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [FfiHistoryItem] {
        let len: Int32 = try readInt(&buf)
        var seq = [FfiHistoryItem]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeFfiHistoryItem.read(from: &buf))
        }
        return seq
    }
}

private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_clipboard_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_history() != 57692) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_history_image_bytes() != 55220) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_is_echo() != 21458) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_pair_begin() != 10858) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_pair_cancel() != 56098) {
        return InitializationResult.apiChecksumMismatch
    }
