        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_pair_poll() != 51350) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_reset_pairing() != 56390) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_send_image() != 34410) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_send_text() != 55285) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_clipboard_core_checksum_method_corehandle_shutdown() != 34459) {
        return InitializationResult.apiChecksumMismatch
